}","style":"自定义","styleLabel":"自定义","stylePrompt":"采用克制、缓慢、细腻的视角推进叙事，注重描写阳光的角度、茶杯的热度、孩童衣角的褶皱等微小细节。通过平实的动作和少量的台词展现时间的流逝与两人关系的渐渐熟络。避免使用宏大的形容词和激烈的情感宣泄，将悲伤、孤独与治愈感溶解在日常扫地、散步、分享一颗糖果等安静的小事中，让故事呈现出如水般静谧平和的质感。","styleExtra":"","playMode":"剧情驱动","playPrompt":"","minChars":4000,"maxChars":7000,"useCharInjection":true,"id":"archive_3279c973-43be-4492-bd4c-25d92e8fa064","charId":"char_1787890623925_cbdea","charName":"莱茵哈鲁特·范·阿斯特雷亚","sources":{"character":"宿主可读字段 + 用户确认","mask":"宿主可读字段 + 用户确认","style":"用户选择或自定义"},"status":"active","createdAt":"2026-10-11T09:45:19.945Z","updatedAt":"2026-10-11T09:45:19.948Z","fragments":[],"sessionRefs":{},"summary":null,"sealDraft":null,"shares":[],"pendingBatch":null}

